CREATE   PROCEDURE dbo.sp_CarWash_BayUtilization
    @StartDate DATE,
    @EndDate   DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartDT DATETIME2 = CAST(@StartDate AS DATETIME2);
    DECLARE @EndDT   DATETIME2 = DATEADD(DAY, 1, CAST(@EndDate AS DATETIME2));
    DECLARE @DaysCount INT = DATEDIFF(DAY, @StartDate, @EndDate) + 1;
    DECLARE @StandardOperatingHoursPerDay DECIMAL(5,2) = 12.0;
    DECLARE @TotalAvailableMinutes DECIMAL(10,2) = @DaysCount * @StandardOperatingHoursPerDay * 60.0;

    SELECT 
        b.BayNumber,
        b.BayName,
        b.BayType,
        b.BayStatus AS CurrentStatus,
        COUNT(o.OrderId) AS TotalWashesHandled,
        ISNULL(SUM(o.TotalAmount), 0.00) AS TotalRevenueGenerated,
        ISNULL(SUM(DATEDIFF(MINUTE, o.StartedDate, o.CompletedDate)), 0) AS TotalActiveMinutes,
        ISNULL(AVG(DATEDIFF(MINUTE, o.StartedDate, o.CompletedDate)), 0) AS AvgServiceMinutesPerCar,
        ROUND(
            (ISNULL(SUM(DATEDIFF(MINUTE, o.StartedDate, o.CompletedDate)), 0) / NULLIF(@TotalAvailableMinutes, 0)) * 100.0, 2
        ) AS UtilizationPercentage
    FROM dbo.BayMaster b
    LEFT JOIN dbo.CarWashOrder o 
        ON b.BayNumber = o.BayId 
       AND o.CreatedDate >= @StartDT AND o.CreatedDate < @EndDT
       AND o.StatusCode IN (60, 70)
    GROUP BY b.BayNumber, b.BayName, b.BayType, b.BayStatus
    ORDER BY b.BayNumber ASC;
END;

storedProcedures.sp_CarWash_PaymentChannelMix:
CREATE   PROCEDURE dbo.sp_CarWash_PaymentChannelMix
    @StartDate DATE,
    @EndDate   DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartDT DATETIME2 = CAST(@StartDate AS DATETIME2);
    DECLARE @EndDT   DATETIME2 = DATEADD(DAY, 1, CAST(@EndDate AS DATETIME2));

    SELECT 
        RTRIM(ISNULL(o.PayMode, 'UNPAID')) AS PaymentChannel,
        ISNULL(pm.Description, RTRIM(o.PayMode)) AS PaymentChannelName,
        COUNT(o.OrderId) AS TransactionCount,
        ISNULL(SUM(o.PackagePrice), 0.00) AS NetSales,
        ISNULL(SUM(o.GSTAmount), 0.00) AS GSTAmount,
        ISNULL(SUM(o.TotalAmount), 0.00) AS TotalAmount,
        ROUND(
            COUNT(o.OrderId) * 100.0 / NULLIF(SUM(COUNT(o.OrderId)) OVER(), 0), 2
        ) AS VolumePercentage,
        ROUND(
            SUM(o.TotalAmount) * 100.0 / NULLIF(SUM(SUM(o.TotalAmount)) OVER(), 0), 2
        ) AS RevenuePercentage
    FROM dbo.CarWashOrder o
    LEFT JOIN dbo.Paymode pm ON RTRIM(o.PayMode) = RTRIM(pm.PayMode)
    WHERE o.CreatedDate >= @StartDT AND o.CreatedDate < @EndDT
      AND o.PaymentStatus = 'PAID'
      AND o.StatusCode != 80
    GROUP BY o.PayMode, pm.Description
    ORDER BY TotalAmount DESC;
END;

storedProcedures.sp_CarWash_DateWiseWashTrend:
CREATE   PROCEDURE dbo.sp_CarWash_DateWiseWashTrend
    @StartDate DATE,
    @EndDate   DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartDT DATETIME2 = CAST(@StartDate AS DATETIME2);
    DECLARE @EndDT   DATETIME2 = DATEADD(DAY, 1, CAST(@EndDate AS DATETIME2));

    SELECT 
        CAST(o.CreatedDate AS DATE) AS OrderDate,
        DATENAME(WEEKDAY, o.CreatedDate) AS DayName,
        COUNT(CASE WHEN o.StatusCode IN (60, 70) THEN 1 END) AS CompletedWashes,
        COUNT(CASE WHEN o.StatusCode = 80 THEN 1 END) AS CancelledOrders,
        COUNT(*) AS TotalOrders,
        ISNULL(SUM(CASE WHEN o.PaymentStatus = 'PAID' AND o.StatusCode != 80 THEN o.TotalAmount ELSE 0 END), 0.00) AS DailyRevenue,
        ISNULL(SUM(CASE WHEN o.PaymentStatus = 'PAID' AND o.StatusCode != 80 THEN o.GSTAmount ELSE 0 END), 0.00) AS DailyGST
    FROM dbo.CarWashOrder o
    WHERE o.CreatedDate >= @StartDT AND o.CreatedDate < @EndDT
    GROUP BY CAST(o.CreatedDate AS DATE), DATENAME(WEEKDAY, o.CreatedDate)
    ORDER BY OrderDate ASC;
END;

storedProcedures.sp_CarWash_OrderSourceSummary:
CREATE   PROCEDURE dbo.sp_CarWash_OrderSourceSummary
    @StartDate DATE,
    @EndDate   DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartDT DATETIME2 = CAST(@StartDate AS DATETIME2);
    DECLARE @EndDT   DATETIME2 = DATEADD(DAY, 1, CAST(@EndDate AS DATETIME2));

    SELECT 
        ISNULL(o.OrderSource, 'KIOSK') AS OrderSource,
        COUNT(*) AS TotalOrders,
        COUNT(CASE WHEN o.StatusCode IN (60, 70) THEN 1 END) AS CompletedWashes,
        ISNULL(SUM(CASE WHEN o.PaymentStatus = 'PAID' AND o.StatusCode != 80 THEN o.TotalAmount ELSE 0 END), 0.00) AS TotalRevenue,
        ROUND(
            COUNT(*) * 100.0 / NULLIF(SUM(COUNT(*)) OVER(), 0), 2
        ) AS SourcePercentage
    FROM dbo.CarWashOrder o
    WHERE o.CreatedDate >= @StartDT AND o.CreatedDate < @EndDT
    GROUP BY o.OrderSource
    ORDER BY TotalRevenue DESC;
END;
